#!/usr/bin/env node
/**
 * Bundle the caption SPEECH PROJECTION into one self-contained IIFE string, for
 * evaluation inside the Chromium the CLI export already has open.
 *
 *   dompurify + lib/core/sanitize-slide-html.mjs + lib/transformers/prose-projection.mjs
 *     →  lib/export/speech-projection-bundle.generated.mjs
 *        (`export const SPEECH_PROJECTION_JS = "<iife source>"`)
 *
 * WHY a string constant, not a module the emulator imports: the consumer is a
 * `page.evaluate`, which takes source TEXT and runs it in the page's realm. The same
 * packaging reason as tools/build-anima-player.js — a browser bundle the Node side
 * only ever hands across CDP.
 *
 * WHY IT EXISTS AT ALL. `lattice-emulator.js`'s `projectDeckSpeechFromHtml` used to
 * build THREE jsdom windows — one to host DOMPurify, one to parse the whole rendered
 * document, and one more per slide to re-parse each sanitized section — while a
 * puppeteer page sat open in the same process. Measured on `examples/read-along-captions.md`
 * (a 2.9 MB self-contained render), medians of five fresh processes: 536ms to
 * `require('jsdom')` cold, 122ms for the sanitizer window, 1715ms to parse the document,
 * 124ms for the nine per-slide windows — 2529ms, against 323ms for the same work in the
 * page, scratch page opened and closed included. jsdom is also a devDependency, so
 * that `require` THREW for anyone running the published CLI and `--captions` wrote no
 * caption track at all. See engineering/decisions/2026-09-20-dom-library-bakeoff.md
 * § "Chromium — already running, fastest of all".
 *
 * The projection KERNEL is unchanged and unduplicated (HARD RULE #1): this bundles the
 * same `prose-projection.mjs` the Studio's Present path already runs in a browser, and
 * the same `createSlideSanitizer` seam, with DOMPurify supplied by the page's own
 * `window` instead of a jsdom one.
 *
 * Flags: --check (freshness gate, exit 1 on drift), --silent.
 */

const esbuild = require('esbuild');
const path = require('node:path');
const fs = require('node:fs');

const ROOT = path.resolve(__dirname, '..');
const EXPORT_DIR = path.join(ROOT, 'lib', 'export');
const OUT_FILE = path.join(ROOT, 'lib', 'export', 'speech-projection-bundle.generated.mjs');

const argv = process.argv.slice(2);
const check = argv.includes('--check');
const silent = argv.includes('--silent') || check;

// The driver, kept BYTE-FOR-BYTE equivalent to the jsdom version it replaces — same
// sanitizer seam, same selector, same whole-array call into `projectDeckToScript`, same
// `.filter(Boolean)`. `projectDeckToScript` is given the WHOLE section array in one call
// (the Studio's `projectSectionsToScript` projects section-at-a-time; that is its own
// divergence and not one to import here), because the CLI's committed `.vtt` goldens were
// produced that way.
//
// ONE CALL for the whole deck, not one per section: a CDP round-trip costs ~0.5ms even
// empty, so the sections are parsed, sanitized and projected inside a single evaluate and
// only the finished script crosses the boundary.
const ENTRY_CONTENTS = `
import DOMPurify from 'dompurify';
import { createSlideSanitizer } from '../core/sanitize-slide-html.mjs';
import { projectDeckToScript } from '../transformers/prose-projection.mjs';

window.__latticeSpeechProjection = {
  projectDeckSpeech(docHtml) {
    const sanitize = createSlideSanitizer(DOMPurify, window);
    const parse = (h) => new DOMParser().parseFromString(h, 'text/html');
    const raw = [...parse(docHtml).querySelectorAll('section[data-lattice-slide]')];
    // Sanitize each section in isolation, then project the clean nodes.
    const clean = raw
      .map((s) => parse(sanitize(s.outerHTML)).querySelector('section[data-lattice-slide]'))
      .filter(Boolean);
    return projectDeckToScript(clean);
  },
};
`;

const BUILD_OPTIONS = {
  stdin: { contents: ENTRY_CONTENTS, resolveDir: EXPORT_DIR, loader: 'js', sourcefile: 'speech-projection.entry.js' },
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['chrome109'],
  minify: true,
  legalComments: 'none',
};

function moduleSource(iife) {
  return (
    '// Auto-generated by tools/build-speech-projection-bundle.js — DO NOT EDIT.\n' +
    '// Sources: dompurify + lib/core/sanitize-slide-html.mjs + lib/transformers/prose-projection.mjs.\n' +
    '// Evaluated inside the export\'s already-open Chromium page; see that script\'s header.\n' +
    '// Rebuild: npm run speech-projection:build\n' +
    `export const SPEECH_PROJECTION_JS = ${JSON.stringify(iife)};\n`
  );
}

async function main() {
  const result = await esbuild.build({ ...BUILD_OPTIONS, write: false });
  const out = moduleSource(result.outputFiles[0].text);
  if (check) {
    const current = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8') : '';
    if (current !== out) {
      console.error('[build-speech-projection-bundle] STALE — run `npm run speech-projection:build` and commit lib/export/speech-projection-bundle.generated.mjs');
      process.exit(1);
    }
    if (!silent) console.log('[build-speech-projection-bundle] up to date.');
    return;
  }
  fs.writeFileSync(OUT_FILE, out);
  if (!silent) console.log(`[build-speech-projection-bundle] wrote ${path.relative(ROOT, OUT_FILE)} (${(out.length / 1024).toFixed(1)} KB IIFE).`);
}

main().catch((err) => {
  console.error('[build-speech-projection-bundle]', err);
  process.exit(1);
});
